use super::*;
#[test]
fn original_resident_paged_source_native_513_records_preserve_order_pointers_and_four_partial_extents(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let policy:serde_json::Value=serde_json::from_str(include_str!("../../../../🧩️composition/📨️emission/📦️owned/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let g:RetainedCloneGrant=serde_json::from_value(policy[law["caller"].as_str().unwrap()].clone()).unwrap();let count=law["records"].as_u64().unwrap()as usize;
 for cut in law["cancelAt"].as_array().unwrap(){let cut=cut.as_u64().unwrap()as usize;let mut pages=semio_framework_value::list::PagedList::<String,{usize::MAX}>::with_payload_page_bytes(17*size_of::<String>()).unwrap();for ordinal in 0..count{pages.push(format!("source-{ordinal}"));}let pointers=pages.iter().map(|id|(id.as_ptr(),id.capacity())).collect::<Vec<_>>();let initial=pages.allocated_bytes()+pages.iter().map(String::capacity).sum::<usize>();let(mut owner,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||PagedSourceIterator::new(pages,String::new));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let backing=owner.backing_bytes();let(mut born,mut released)=(0,0);
  for ordinal in 0..cut{let mut record=None;for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.take_next_into(&mut record,denied));assert_eq!(result.unwrap(),Some(Default::default()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(record.is_none());assert_eq!(owner.peek().unwrap().as_ptr(),pointers[ordinal].0);assert_eq!(owner.backing_bytes(),backing);}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.take_next_into(&mut record,g));let progress=result.unwrap().unwrap();assert!(progress.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));let record=record.unwrap();assert_eq!(record,format!("source-{ordinal}"));assert_eq!((record.as_ptr(),record.capacity()),pointers[ordinal]);assert_eq!(owner.backing_bytes(),backing);let mut retirement=semio_framework_value::retirement::controlled::ControlledRetirement::new(record).ok().unwrap();for _ in 0..4096{if retirement.terminal_is_empty(){break}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||retirement.step(g).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;}assert!(retirement.terminal_is_empty());}
  for _ in 0..100000{if owner.terminal_is_empty(){break}let d=owner.demands(g.maximum_copy_bytes).unwrap();for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}]{if denied==g||d.copy_bytes==0&&denied.maximum_copy_bytes!=g.maximum_copy_bytes||d.capacity_bytes==0&&denied.maximum_capacity_bytes!=g.maximum_capacity_bytes||d.release_bytes==0&&denied.maximum_release_bytes!=g.maximum_release_bytes{continue}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;}
  assert!(owner.terminal_is_empty());assert_eq!(initial+born,released);let((),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));eprintln!("[DEBUG] Original513 paged source cut={cut} backing={backing} initial={initial} birth={born} release={released}; ordered native pointers and paid terminal pages");
 }
}
